#include <atomic>
#include <cstdint>

// WHY THE ORIGINAL WAS A RACE: a memory location is a scalar object or a
// maximal sequence of adjacent non-zero-width bit-fields. `logged_in` and
// `heartbeat_missed` are therefore ONE location, and the two unsynchronized
// writes conflict - undefined behaviour, not a lost bit.
//
// Two separate std::atomic<bool> members would fix the race (distinct
// scalar objects are distinct locations) but would NOT satisfy (c): two
// loads of two atomics observe two independent modification orders, so the
// monitor could report a pair that never existed simultaneously.
class SessionFlags {
public:
    static constexpr std::uint8_t logged_in = 1u << 0;
    static constexpr std::uint8_t heartbeat_missed = 1u << 1;

    // fetch_or is a read-modify-write: it reads the immediately preceding
    // value in this object's modification order, so concurrent setters
    // cannot lose each other's bit the way a load/store pair would.
    void set(std::uint8_t mask) {
        bits_.fetch_or(mask, std::memory_order_relaxed);
    }

    void clear(std::uint8_t mask) {
        bits_.fetch_and(static_cast<std::uint8_t>(~mask),
                        std::memory_order_relaxed);
    }

    // ONE atomic load: both bits come from a single point in the object's
    // modification order, so the pair is always one that really existed.
    std::uint8_t snapshot() const {
        return bits_.load(std::memory_order_relaxed);
    }

private:
    // Relaxed throughout: these flags publish no other state. If a setter
    // ever needs to publish a payload alongside a bit, that store becomes
    // release and the monitor's load becomes acquire.
    std::atomic<std::uint8_t> bits_{0};
};

static_assert(sizeof(SessionFlags) == 1);

#include <atomic>

struct StopReason {
    int code;
    const char* text;  // a string literal: nothing owned, nothing to free
};

// SINGLE CONTROLLER: `reason` is a plain object written without
// synchronization, so exactly one thread may call request_stop().
StopReason reason{};
std::atomic<bool> stopping{false};

void request_stop(int code, const char* text) {
    reason = StopReason{code, text};                  // (1)
    stopping.store(true, std::memory_order_release);  // (2)
}

bool should_stop(StopReason& out) {
    if (!stopping.load(std::memory_order_acquire)) {  // (3)
        // Reading `false` reads from NO release operation, so no
        // synchronizes-with edge exists and `reason` must not be touched.
        return false;
    }
    out = reason;                                     // (4)
    return true;
}

// THE EDGES, for a worker that starts before the stop:
//   (1) is sequenced-before (2)   - same thread, evaluation order.
//   (2) synchronizes-with (3)     - BECAUSE (3) read the value (2) wrote.
//   (3) is sequenced-before (4)   - same thread.
//   Transitively (1) happens-before (4), so the conflicting plain accesses
//   to `reason` are ordered and race-free.
//
// CASE (2) OF THE CONTRACT - stop requested before any worker exists:
//   Starting a thread synchronizes with the beginning of that thread's
//   function. Everything the controller did before std::thread's
//   constructor - including (1) and (2) - therefore happens before every
//   evaluation in the worker, and the worker's first poll already observes
//   both the flag and the reason. No extra mechanism is needed, and this is
//   the edge people forget when they "fix" the race by re-ordering
//   thread creation.

#include <atomic>
#include <cstdint>

// is_always_lock_free is the compile-time constant, so a target that would
// give us a library lock on the admission hot path fails the build instead.
static_assert(std::atomic<std::uint64_t>::is_always_lock_free,
              "admission control must not fall back to a library lock");

class AdmissionGate {
public:
    explicit AdmissionGate(std::uint64_t capacity) : capacity_(capacity) {}

    bool try_admit() {
        // fetch_add returns the value from BEFORE the increment, so
        // `ticket` is this caller's unique zero-based position. Two
        // callers can never receive the same ticket, because each RMW
        // reads the modification immediately preceding it in this
        // object's modification order.
        //
        // Relaxed is sufficient: only this object's own value and
        // modification order matter. Nothing else is being published
        // through the counter, and admission does not order any other
        // memory.
        std::uint64_t ticket = used_.fetch_add(1, std::memory_order_relaxed);
        return ticket < capacity_;
    }

    // Called by the window timer while no admission is in flight.
    void begin_window() { used_.store(0, std::memory_order_relaxed); }

private:
    std::uint64_t capacity_;
    std::atomic<std::uint64_t> used_{0};
};

// THE OVERSHOOT. Every caller increments, including rejected ones, so
// after a burst `used_` can be far above `capacity_`. That is harmless
// because the decision is made from the RETURNED ticket, never from a
// later load of the counter: tickets 0 .. capacity_-1 are handed out
// exactly once each, so exactly capacity_ callers see `true`.
//
// The tempting "fix" - load, compare, then store the increment - is the
// lost-update bug: two callers read the same value and both admit
// themselves. Rejecting-then-decrementing is worse still, since the
// decrement can race a concurrent window reset.

#include <atomic>

bool record_high(std::atomic<long>& peak, long candidate) {
    // One load; the failed CAS refreshes `observed` for us.
    long observed = peak.load(std::memory_order_relaxed);

    while (candidate > observed) {
        // weak: this loop already retries, so a spurious failure costs
        // one more iteration and avoids the nested retry a strong CAS
        // may have to perform on an LL/SC machine.
        //
        // success: relaxed - we publish no other state through `peak`.
        // failure: relaxed - the observed value is only compared, never
        // used to reach other memory. (Release/acq_rel are ill-formed
        // for the failure path: a failed CAS performs no write.)
        if (peak.compare_exchange_weak(observed, candidate,
                                       std::memory_order_relaxed,
                                       std::memory_order_relaxed)) {
            return true;
        }
    }
    return false;
}

#include <atomic>

int flushed_bytes = 0;  // plain payload; written only by the winner

std::atomic<bool> claimed{false};
std::atomic<bool> complete{false};

int flush_once() {
    // ONE read-modify-write decides the winner. exchange returns the value
    // from before the store, so exactly one caller can observe `false`.
    //
    // A load-then-store claim -
    //     if (!claimed.load()) { claimed.store(true); ... }
    // - is the lost-update bug applied to a decision: two callers can both
    // load `false` and both run the flush. Each access is atomic; the pair
    // is not.
    //
    // acq_rel: the acquire half orders this caller's later reads after the
    // exchange, and the release half means a future claimant's acquire can
    // see what this caller did before it.
    if (!claimed.exchange(true, std::memory_order_acq_rel)) {
        flushed_bytes = 4096;  // the one-time work

        // Release: publishes the write above to any caller whose acquire
        // load below reads THIS value.
        complete.store(true, std::memory_order_release);
        return flushed_bytes;
    }

    // WHY A SECOND FLAG IS REQUIRED: `claimed == true` says only that
    // somebody started, not that they finished. Returning here would
    // violate contract (2) and would read `flushed_bytes` while the
    // winner is still writing it - a data race, not merely a stale value.
    while (!complete.load(std::memory_order_acquire)) {
    }
    return flushed_bytes;  // race-free: the acquire read the release
}

#include <array>
#include <atomic>
#include <cstddef>

inline constexpr std::size_t producers = 4;

// Distinct array elements are distinct memory locations and each has
// exactly one writer, so these plain writes never conflict with each other.
std::array<int, producers> batch{};
std::atomic<std::size_t> outstanding{producers};
int flushed_total = 0;

void contribute(std::size_t index, int value) {
    batch[index] = value;

    // RELEASE ON EVERY DECREMENT, and nothing more: a producer that is not
    // the last one pays one release RMW and goes home. The release half
    // publishes this producer's slot write.
    if (outstanding.fetch_sub(1, std::memory_order_release) == 1) {
        // fetch_sub returns the count from BEFORE the decrement, so 1
        // means this call took it to zero. Testing for == 0 is the classic
        // off-by-one: it never fires.

        // WHY THE FLUSHER MAY READ THE OTHER SLOTS. All four decrements
        // are read-modify-writes, so they form a release sequence in
        // `outstanding`'s modification order, headed by the first of them.
        // This final RMW read a value from that sequence, so the acquire
        // fence sequenced after it makes every earlier producer's released
        // slot write visible before the reads below.
        //
        // A purely relaxed final decrement would still elect exactly one
        // winner - relaxed RMWs are still atomic and still serialised on
        // this object - but would acquire nothing, and the flush could read
        // slots whose writes are not yet ordered before it.
        std::atomic_thread_fence(std::memory_order_acquire);

        int total = 0;
        for (int slot : batch) {
            total += slot;
        }
        flushed_total = total;
    }
}

#include <array>
#include <atomic>
#include <cstddef>

std::array<std::atomic<int>, 4> scratch{};
std::atomic<int> filled{0};    // carrier: producer -> consumer
std::atomic<int> drained{0};   // carrier: consumer -> producer

// PRODUCER SIDE, outbound: FENCE-FENCE with the consumer.
// A release fence sequenced before the relaxed carrier store synchronizes
// with an acquire fence sequenced after a relaxed load that READS THAT
// STORE. Both carrier accesses may stay relaxed; the reads-from
// relationship is what carries the edge.
void publish(int generation, const std::array<int, 4>& values) {
    for (std::size_t i = 0; i < values.size(); ++i) {
        scratch[i].store(values[i], std::memory_order_relaxed);
    }
    std::atomic_thread_fence(std::memory_order_release);
    filled.store(generation, std::memory_order_relaxed);
    // If this store were hoisted ABOVE the fence, the consumer could read
    // the new generation while the slot stores are still unordered with
    // respect to it: the edge is silently gone and nothing in the source
    // looks wrong.
}

// CONSUMER SIDE: the acquire fence is the other end of the fence-fence
// pair. Returning 0 means the carrier load did not read the publication,
// so no edge exists at all and the payload must not be touched.
int consume(int generation, std::array<int, 4>& out) {
    if (filled.load(std::memory_order_relaxed) != generation) {
        return 0;
    }
    std::atomic_thread_fence(std::memory_order_acquire);
    for (std::size_t i = 0; i < out.size(); ++i) {
        out[i] = scratch[i].load(std::memory_order_relaxed);
    }
    // A payload load hoisted ABOVE this fence could observe a
    // pre-publication value: an acquire fence orders only what follows it.

    // RETURN HANDOFF: a RELEASE STORE, not a fence, so the producer half
    // below is the ATOMIC-FENCE pattern.
    drained.store(generation, std::memory_order_release);
    return 1;
}

// PRODUCER SIDE, inbound: ATOMIC-FENCE. A release write X synchronizes
// with an acquire fence sequenced after an atomic read that READS X - so
// the relaxed load below plus the fence is enough to observe everything
// the consumer did before its release store, and the buffer is safe to
// overwrite.
bool reusable(int generation) {
    if (drained.load(std::memory_order_relaxed) != generation) {
        return false;
    }
    std::atomic_thread_fence(std::memory_order_acquire);
    return true;
}

#include <array>
#include <atomic>
#include <cstddef>
#include <mutex>

struct Session {
    int venue_id;
    int max_orders_per_second;
};

inline constexpr std::size_t max_venues = 64;

// One published slot per venue. std::atomic<Session*>, not Session*: an
// unlocked fast-path read of a plain pointer would conflict with the
// writer's store even though the writer holds the mutex, and that is a
// data race regardless of how the value is later used.
std::array<std::atomic<Session*>, max_venues> sessions{};
std::mutex sessions_mutex;

Session& session_for(std::size_t venue) {
    // (1) ACQUIRE, not relaxed. Contract (3) is the reason: a non-null
    // pointer must arrive together with the visibility of the pointee's
    // initialisation, or the caller reads uninitialised fields. Relaxed
    // would publish the address and nothing behind it.
    Session* session = sessions[venue].load(std::memory_order_acquire);
    if (session != nullptr) {
        return *session;  // contract (2): no mutex on this path
    }

    std::lock_guard lock{sessions_mutex};

    // (2) SECOND CHECK, under the lock. Another thread may have published
    // this venue's session while this one waited for the mutex; without
    // this load we would construct a second Session and contract (1)
    // would fail. The mutex serialises the writers, it does not undo an
    // observation made before it was held.
    session = sessions[venue].load(std::memory_order_acquire);
    if (session == nullptr) {
        // (3) Construction completes HERE, entirely sequenced before...
        session = new Session{static_cast<int>(venue), 100};

        // (4) ...the release store, which publishes it. The release covers
        // only what precedes it: writing session->max_orders_per_second
        // AFTER this line would race with fast-path readers who have
        // already acquired the pointer. Treat a published object as
        // immutable unless a separate protocol synchronizes the mutation.
        sessions[venue].store(session, std::memory_order_release);
    }
    return *session;
}

// WHY NOT A FUNCTION-LOCAL static? Magic statics already give thread-safe
// one-time construction, and for a single object that is the right answer
// - it is this whole function in one line. But a static initialises once
// per DECLARATION, and the venue is a runtime value: `static Session s{...}`
// inside this function would construct one session and hand it to every
// venue. Hand-written double-checked locking is for exactly the lifetimes
// a static cannot express - here, one object per runtime-selected slot.

