#include <atomic>
#include <csignal>

// A signal handler may touch only a lock-free atomic (or a
// volatile std::sig_atomic_t). Make that a build requirement: a target
// where std::atomic<bool> could take a library lock must not compile.
static_assert(std::atomic<bool>::is_always_lock_free,
              "shutdown flag must be usable from a signal handler");

std::atomic<bool> stopping{false};

extern "C" void on_sigint(int) {
    // Relaxed is enough HERE: the handler runs in the polling thread
    // itself, so sequenced-before already orders it against the loop.
    stopping.store(true, std::memory_order_relaxed);
}

void request_stop() {
    // Release, because a control thread may also publish state that the
    // polling thread reads once it observes the flag.
    stopping.store(true, std::memory_order_release);
}

void poll() {
    std::signal(SIGINT, on_sigint);
    while (!stopping.load(std::memory_order_acquire)) {
    }
}

// WHAT volatile GAVE, AND DID NOT:
//   It makes each access an observable side effect the compiler may not
//   elide or merge. That is the whole list. It provides
//     - no atomicity of the access,
//     - no happens-before edge with another thread,
//     - no exemption from the data-race rule.
//   So the starter was still undefined behaviour when a second THREAD
//   called request_stop(); it merely stopped the compiler from hoisting
//   the load, which made the symptom go away on one build.
//
// WHY THE TWO CASES DIFFER:
//   A signal handler runs IN the interrupted thread, so there is no
//   cross-thread edge to establish and only compiler-visible access
//   behaviour is at stake - which is exactly the narrow guarantee
//   volatile std::sig_atomic_t was designed for, and what
//   std::atomic_signal_fence constrains. A second thread is a different
//   problem: nothing but a real atomic (or a lock) makes those
//   conflicting accesses race-free.

#include <atomic>

int data = 0;                     // plain payload
std::atomic<bool> ready{false};
std::atomic<bool> relayed{false};

void produce() {
    data = 42;                                          // A
    ready.store(true, std::memory_order_release);       // B
}

void relay() {
    if (ready.load(std::memory_order_acquire)) {        // C
        relayed.store(true, std::memory_order_release); // D
    }
}

int consume() {
    if (relayed.load(std::memory_order_acquire)) {      // E
        return data;                                    // F - must be 42
    }
    return -1;
}

// THE CHAIN, when C reads true and E reads true:
//   A sequenced-before B; B synchronizes-with C (C read B's value);
//   C sequenced-before D; D synchronizes-with E (E read D's value);
//   E sequenced-before F.
//   Happens-before is the TRANSITIVE closure of those edges, so
//   A happens-before F across three threads: the read is race-free and
//   must observe 42. Note that no thread is required to run at any
//   particular time - if C reads false, the relay does nothing and E
//   reads false, and the guarantee is vacuous rather than violated.
//
// WEAKENING 1 - relay's LOAD (C) becomes relaxed: BREAKS IT.
//   A relaxed load creates no synchronizes-with edge even when it reads
//   the release store's value, so B no longer synchronizes with C and A
//   is not ordered before D. The consumer still synchronizes with the
//   relay, but the relay has nothing of the producer's to pass on. This
//   is the counter-intuitive half: the operation that fails is in a
//   thread that never touches `data`.
//
// WEAKENING 2 - relay's STORE (D) becomes relaxed: BREAKS IT.
//   E's acquire creates an edge only with a RELEASE operation on the
//   object it read from. A relaxed store is not a release, so no edge
//   forms at D->E, and the consumer's read of `data` is unordered with
//   respect to A - a data race, not merely a stale value.
//
// Both halves of the relay are load-bearing: the acquire imports the
// producer's state, and the release re-exports it. That is exactly the
// role `memory_order_acq_rel` plays when the relay is a single RMW
// rather than a load and a store.
